#include "render_device_api.hpp"
#include "shared/sea_camera_medium.hpp"
#include <SDL.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <thread>
#include <chrono>
extern "C" void StormMetalPublishSeaCamera(void*,float);
void check(bool x,const char*msg){if(!x){fprintf(stderr,"FAIL %s\n",msg);std::exit(1);}}
int main(int argc,char**argv){if(argc>1)setenv("STORM_METAL_AA_MODE",argv[1],1);if(argc>2)setenv("STORM_METAL_UPSCALING",argv[2],1);check(SDL_Init(SDL_INIT_VIDEO)==0,"SDL");auto*w=SDL_CreateWindow("boundary fixture",0,0,64,64,SDL_WINDOW_HIDDEN|SDL_WINDOW_METAL);check(w,"window");storm_render::Presentation p{};p.width=p.height=64;p.colorFormat=storm_render::AssetFormat::A8R8G8B8;storm_render::Device*d=nullptr;check(storm_render::succeeded(storm_render::createMetalDevice(w,&p,&d)),"device");storm_render::Matrix m{};m._11=m._22=m._33=m._44=1.f;d->SetTransform(storm_render::TransformView,&m);d->SetTransform(storm_render::TransformProjection,&m);storm_render::Viewport vp{0,0,64,64,0,1};d->SetViewport(&vp);storm_render::Surface *target=nullptr,*readback=nullptr;check(storm_render::succeeded(d->GetRenderTarget(&target)),"target");check(storm_render::succeeded(d->CreateOffscreenPlainSurface(64,64,storm_render::AssetFormat::A8R8G8B8,&readback)),"readback");auto pixel=[&](int x,int y){check(storm_render::succeeded(d->GetRenderTargetData(target,readback)),"get pixels");storm_render::LockedRect r{};check(storm_render::succeeded(readback->LockRect(&r,nullptr,storm_render::lock::readOnly)),"lock");uint32_t out;memcpy(&out,(char*)r.pBits+y*r.Pitch+x*4,4);readback->UnlockRect();return out;};auto clear=[&](){check(storm_render::succeeded(d->Clear(storm_render::clear::color|storm_render::clear::depth,0xffc878b4,1)),"clear");};
 clear();StormMetalPublishSeaCamera(d,-1);check(storm::sea_camera_medium::depth()==-1,"above publication");std::this_thread::sleep_for(std::chrono::milliseconds(600));storm_render::markSceneBoundary(d,storm_render::SceneBoundary::Hud);auto above=pixel(32,32);check((above&0xffffff)==0xc878b4,"above unchanged");d->Present();
 unsigned previous=(above>>16)&255;for(float depth: {0.01f,0.4f,2.f,20.f}){clear();StormMetalPublishSeaCamera(d,depth);storm_render::markSceneBoundary(d,storm_render::SceneBoundary::Hud);auto sample=pixel(32,32);unsigned red=(sample>>16)&255;printf("transition depth %.2f pixel=%08x\n",depth,sample);check(red<=previous,"continuous transition monotonic");previous=red;d->Present();}clear();StormMetalPublishSeaCamera(d,-1);
 clear();storm_render::Surface*other=nullptr;check(storm_render::succeeded(d->CreateRenderTarget(64,64,storm_render::AssetFormat::A8R8G8B8,&other)),"offscreen target");check(storm_render::succeeded(d->SetRenderTarget(other)),"bind offscreen");StormMetalPublishSeaCamera(d,42);check(storm::sea_camera_medium::depth()==-1,"offscreen cannot publish");check(storm_render::succeeded(d->SetRenderTarget(target)),"restore main target");other->Release();StormMetalPublishSeaCamera(d,20);storm_render::markSceneBoundary(d,storm_render::SceneBoundary::Hud);auto wet=pixel(32,32);printf("above=%08x wet=%08x\n",above,wet);check((wet&0xffffff)!=(above&0xffffff),"main scene attenuated");storm_render::markSceneBoundary(d,storm_render::SceneBoundary::Hud);check(pixel(32,32)==wet,"marker only once");check(storm_render::succeeded(d->Clear(storm_render::clear::color,0xff2266ee,1)),"HUD paint");d->Present();check((pixel(32,32)&0xffffff)==0x2266ee,"HUD remains unchanged");
 clear();StormMetalPublishSeaCamera(d,20);d->Present();auto fallback=pixel(32,32);printf("fallback=%08x\n",fallback);check((fallback&0xffffff)!=(above&0xffffff),"Present fallback");
 clear();m._11=m._22=m._33=m._44=-1.f;d->SetTransform(storm_render::TransformProjection,&m);StormMetalPublishSeaCamera(d,20);storm_render::markSceneBoundary(d,storm_render::SceneBoundary::Hud);auto negativeW=pixel(32,32);printf("negativeW=%08x\n",negativeW);check(negativeW==wet,"homogeneous sign invariance");d->Present();m._11=m._22=m._33=m._44=1.f;d->SetTransform(storm_render::TransformProjection,&m);
 clear();vp={16,16,32,32,0,1};d->SetViewport(&vp);StormMetalPublishSeaCamera(d,20);storm_render::markSceneBoundary(d,storm_render::SceneBoundary::Hud);auto outside=pixel(2,2),inside=pixel(32,32);printf("viewport outside=%08x inside=%08x\n",outside,inside);check((outside&0xffffff)==0xc878b4&&(inside&0xffffff)!=0xc878b4,"viewport bounds");
 readback->Release();target->Release();d->Release();SDL_DestroyWindow(w);SDL_Quit();puts("PASS boundary, HUD, fallback, viewport");}
